css:
/* Switches: off is a visible grey track with an outline and a light thumb; on is rocoto red with a white thumb. */
.dark [data-slot="switch"] { background-color: #3A3E45 !important; box-shadow: inset 0 0 0 1px #575D66 !important; }
.dark [data-slot="switch"] > * { background-color: #C9CDD3 !important; }
:root:not(.dark) [data-slot="switch"] { background-color: #BEC4CC !important; box-shadow: inset 0 0 0 1px #A3AAB3 !important; }
:root:not(.dark) [data-slot="switch"] > * { background-color: #FFFFFF !important; box-shadow: 0 1px 2px rgba(22,24,28,.25) !important; }
[data-slot="switch"][data-checked], [data-slot="switch"][aria-checked="true"], [data-slot="switch"][data-state="checked"] { background-color: #F0483A !important; box-shadow: none !important; }
:root:not(.dark) [data-slot="switch"][data-checked], :root:not(.dark) [data-slot="switch"][aria-checked="true"], :root:not(.dark) [data-slot="switch"][data-state="checked"] { background-color: #C4271C !important; }
[data-slot="switch"][data-checked] > *, [data-slot="switch"][aria-checked="true"] > *, [data-slot="switch"][data-state="checked"] > * { background-color: #FFFFFF !important; }
